export function mergeIntervalInterval(intervals) {
  if (!Array.isArray(intervals)) {
    throw new Error("Input must be an array.");
  }

  const processedInterval = (interval) => {
    if (!Array.isArray(interval) || interval.length !== 2 ||
        !Number.isFinite(interval[0]) || !Number.isFinite(interval[1])) {
      throw new Error("Interval must be an array of two finite numbers.");
    }
    const [start, end] = [...interval];
    return start > end ? [end, start] : [start, end];
  };

  const validatedAndProcessed = intervals.map(processedInterval);

  if (validatedAndProcessed.length === 0) {
    return [];
  }

  // Sort by start time
  const sortedInterval = [...validatedAndProcessed].sort((a, b) => a[0] - b[0]);

  const merged = [];
  let currentInterval = [...sortedInterval[0]];

  for (let i = 1; i < sortedInterval.length; i++) {
    const nextInterval = sortedInterval[i];
    const [currentStart, currentEnd] = currentInterval;
    const [nextStart, nextEnd] = nextInterval;

    // Check for overlap or touching: nextStart <= currentEnd
    if (nextStart <= currentEnd) {
      // Merge: extend the end of the current interval
      currentInterval = [currentStart, Math.max(currentEnd, nextEnd)];
    } else {
      // No overlap, push current and start a new one
      merged.push([...currentInterval]);
      currentInterval = [...nextInterval];
    }
  }

  // Push the last processed interval
  merged.push([...currentInterval]);

  return merged;
}
